(function () {
  'use strict'
  const { build, fmt, clean, pctText, plural, smallSampleText, exceptionsText, MIN_SAMPLE, duration, date, list } = EbrReport
  const data = JSON.parse(document.getElementById('report-data').textContent)
  const m = build(data)
  // The CyberSOC monthly sections (cybersoc-model.js), derived from the same data after the EBR model.
  const cs = EbrCyberSoc.build(data, m)
  const esc = value => clean(value).replace(/&/g, '&amp;').replace(/"/g, '&quot;').replace(/'/g, '&#39;')
  const report = document.getElementById('report')
  const SEVERITY = ['High', 'Medium', 'Low', 'Informational']
  const source = text => text ? `<p class="source">${esc(text)}</p>` : ''
  const clamp = v => Math.max(0, Math.min(100, Number(v) || 0))
  const bar = (pct, label, tone = '') => `<div class="track" role="img" aria-label="${esc(label)}"><span class="fill ${tone}" style="width:${clamp(pct).toFixed(2)}%"></span></div>`
  const ring = (pct, label, tone = '') => {
    const r = 42, c = 2 * Math.PI * r, v = clamp(pct)
    return `<svg class="ring ${tone}" viewBox="0 0 100 100" role="img" aria-label="${esc(label)}"><circle class="ring-track" cx="50" cy="50" r="${r}"/><circle class="ring-fill" cx="50" cy="50" r="${r}" stroke-dasharray="${(c * v / 100).toFixed(2)} ${c.toFixed(2)}" transform="rotate(-90 50 50)"/><text x="50" y="54" text-anchor="middle">${esc(pctText(pct))}</text></svg>`
  }
  const sparkline = (points, label) => {
    if (!points || points.length < 2) return ''
    const w = 220, h = 54, pad = 6
    const values = points.map(p => p.pct), lo = Math.min(...values), hi = Math.max(...values), range = hi - lo || 1
    const xy = points.map((p, i) => [pad + i * (w - 2 * pad) / (points.length - 1), h - pad - (p.pct - lo) * (h - 2 * pad) / range])
    const last = xy[xy.length - 1]
    return `<svg class="spark" viewBox="0 0 ${w} ${h}" role="img" aria-label="${esc(label)}"><polyline points="${xy.map(p => p.map(n => n.toFixed(1)).join(',')).join(' ')}"/><circle cx="${last[0].toFixed(1)}" cy="${last[1].toFixed(1)}" r="4"/></svg><div class="spark-axis"><span>${esc(points[0].label)}</span><span>${esc(points[points.length - 1].label)}</span></div>`
  }
  // A control at E that leaves resources out names its exceptions, so meeting the threshold reads differently from
  // having none left out (Oct 15, 2026). A device code or legacy authentication block in force names the
  // accounts whose sign-ins fell under its exclusions the same way (issue #27).
  const exceptionText = exceptionsText
  // A ratio control on a small sample keeps its mark and carries the flag beside it (issue #24).
  const sampleText = c => c.mark && c.smallSample ? 'small sample' : ''
  const markChip = (mark, ...flags) => mark ? `<span class="mark mark-${mark.toLowerCase()}" title="${mark === 'E' ? 'Enforced' : mark === 'P' ? 'Partial' : 'Not enforced'}${flags.filter(Boolean).map(f => `, ${esc(f)}`).join('')}">${mark}</span>` : ''
  const smallNote = n => n ? ` (${smallSampleText(n)})` : ''
  const footer = (number, topic) => `<footer class="page-footer"><span class="wordmark">atmosera<span>.</span></span><span>${esc(m.client)} · CyberSOC monthly report · ${esc(topic)}</span><span>${number}</span></footer>`
  const heading = (n, title, subtitle) => `<header class="section-heading"><p class="eyebrow">CyberSOC monthly report · ${esc(cs.month.label)} · ${n}</p><h2>${esc(title)}</h2><p>${esc(subtitle)}</p></header>`
  const scopeLine = `${esc(m.period.label)} · Posture read ${esc(m.readDate)} · ${m.subscriptions} ${m.subscriptions === 1 ? 'subscription' : 'subscriptions'} · ${m.workspaces.length} Sentinel ${m.workspaces.length === 1 ? 'workspace' : 'workspaces'}`
  // Shared pieces of the CyberSOC pages. Cells arrive escaped. The first cell of a row is its header.
  const table = (caption, head, rows, numeric = []) => `<div class="table-scroll"><table>${caption ? `<caption>${esc(caption)}</caption>` : ''}<thead><tr>${head.map((h, i) => `<th scope="col"${numeric.includes(i) ? ' class="num"' : ''}>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.map(r => `<tr>${r.map((c, i) => i === 0 ? `<th scope="row">${c}</th>` : `<td${numeric.includes(i) ? ' class="num"' : ''}>${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`
  const range = n => Array.from({ length: n }, (_, i) => i + 1)
  const tileStrip = (title, list) => list.length ? `<div class="strip"><p class="strip-title">${esc(title)}</p><div class="tiles tiles-${list.length}">${list.map(t => `<article class="tile"><span class="tile-value">${esc(t.value)}</span><h3>${esc(t.label)}</h3><p>${esc(t.sub)}</p>${source(t.source)}</article>`).join('')}</div></div>` : ''
  const reportIndex = cs.months.findIndex(x => x.report)
  const prevLabel = reportIndex > 0 ? cs.months[reportIndex - 1].label : ''
  const periodWord = cs.months.length === 3 ? 'the 90 days' : 'the period'

  // 01 Executive summary: the report month, with the 90-day trend beside it.
  const tiles = (cs.headline.length ? cs.headline : m.headline).map(t => `<article class="tile"><span class="tile-value">${esc(t.value)}</span><h3>${esc(t.label)}</h3><p class="${t.tone === 'up' ? 'up' : ''}">${esc(t.sub)}</p>${source(t.source)}</article>`).join('')
  const tierDefs = [
    ['outcomes', 'Tier 1 · Outcomes', 'Did the program hold'],
    ['controls', 'Tier 2 · Control effectiveness', 'What is actually enforced'],
    ['hardening', 'Tier 3 · What we are hardening next', 'Proposed in priority order'],
    ['benchmark', 'Tier 4 · Vendor benchmark', 'Context, not the objective']
  ]
  const tiers = tierDefs.map(([key, eyebrow, title]) => `<div class="tier tier-${key}"><p class="eyebrow">${esc(eyebrow)}</p><h3>${esc(title)}</h3>${m.tiers[key].length ? m.tiers[key].map(r => `<div class="tier-row"><span>${esc(r.label)}${r.note ? ` <em class="tier-note">(${esc(r.note)})</em>` : ''}</span><strong>${esc(r.value)}</strong></div>`).join('') : `<p class="tier-empty">${key === 'hardening' ? 'No open hardening items from this collection.' : 'Readings are completed in the review.'}</p>`}</div>`).join('')
  const headCount = (cs.headline.length ? cs.headline : m.headline).length
  const glanceSources = [...new Set(cs.glance.rows.map(r => r.source))]
  const glance = cs.glance.rows.length ? `<div class="glance"><h2>${esc(cs.month.label)} at a glance</h2><p class="small">The report month beside the months before it, over ${esc(cs.window.label)}.${prevLabel ? ` The change column compares with ${esc(prevLabel)} and makes no judgment: more alerts can mean more coverage as well as more activity.` : ''}</p>${table('', ['Measure', ...cs.glance.months, ...(prevLabel ? [`Change from ${prevLabel}`] : [])], cs.glance.rows.map(r => [esc(r.label), ...r.values.map(esc), ...(prevLabel ? [esc(r.change)] : [])]), range(cs.glance.months.length))}${source(`Evidence ${glanceSources.join(', ')}. Scores are percentages of the maximum each was read against.`)}</div>` : ''
  const brief = cs.summary.length ? `<div class="month-brief"><p class="eyebrow dark">${esc(cs.month.label)} in brief</p>${cs.summary.map(t => `<p>${esc(t)}</p>`).join('')}</div>` : ''
  const highlights = cs.highlights.length ? `<div class="highlights"><h3>Analyst highlights for ${esc(cs.month.label)}</h3><div class="highlight-grid">${cs.highlights.map(h => `<article><h4>${esc(h.title)}</h4><p>${esc(h.summary)}</p>${source(`${h.reference}, reviewed ${h.reviewed}, from the reviewed context file.`)}</article>`).join('')}</div></div>` : ''
  const summary = `<section class="page summary-page" id="summary">
    <header class="hero"><p class="eyebrow">Managed security services · CyberSOC monthly report</p><h1>CyberSOC monthly security report</h1><div class="hero-rule"></div><p class="hero-client">${esc(m.client)}</p><p class="hero-caption">${esc(cs.month.label)}, with the 90-day trend. What the SOC handled, the threats observed, the vulnerabilities open and the controls in force.</p><p class="hero-meta">${scopeLine}</p></header>
    <div class="page-body">
      <div class="strip"><p class="strip-title">${esc(cs.month.label)} · managed security services in force</p><div class="tiles tiles-${headCount}">${tiles}</div></div>
      ${brief}${glance}${highlights}
      <div class="tiers-block"><h2>How we report posture</h2><p>Posture is reported for the whole tenant, not for Azure resources alone, and never as a single vendor percentage. We weight what we report in this order.</p><div class="tiers">${tiers}</div></div>
      <div class="what-next"><span class="eyebrow">In this report</span><p>${esc(cs.whatNext)}</p></div>
    </div>${footer('01', 'Executive summary')}</section>`

  // 02 Security operations
  const responseTiles = []
  if (m.response) responseTiles.push({ value: m.response.median.value, label: m.response.median.label, sub: m.response.median.note, source: m.response.median.source })
  if (m.response?.p90) responseTiles.push({ value: m.response.p90.value, label: m.response.p90.label, sub: m.response.p90.note, source: m.response.p90.source })
  if (m.alerts) responseTiles.push({ value: fmt(m.alerts.triaged), label: `Alerts triaged${m.detections ? ' across ' + m.detections.sources : ''}`, sub: m.alerts.analystMode ? `${fmt(m.alerts.automation)} more were closed by automation rules.` : `${esc(m.period.label)}.`, source: m.alerts.source })
  // The confirmed threat tile counts a classification, never an investigation.
  if (m.alerts && m.alerts.truePositives !== null && responseTiles.length < 4) responseTiles.push({ value: fmt(m.alerts.truePositives), label: 'Confirmed threats', sub: 'Alerts the SOC classified as true positives.', source: m.alerts.source })
  if (m.detections && responseTiles.length < 4) responseTiles.push({ value: fmt(m.detections.total), label: 'Detections correlated into alerts', sub: `Across ${m.detections.sources}.`, source: m.detections.source })
  const responseStrip = responseTiles.length ? `<div class="strip"><p class="strip-title">Response performance · measured, not asserted</p><div class="tiles tiles-${responseTiles.length}">${responseTiles.map(t => `<article class="tile"><span class="tile-value">${esc(t.value)}</span><h3>${esc(t.label)}</h3><p>${esc(t.sub)}</p>${source(t.source)}</article>`).join('')}</div></div>` : ''
  // One fixed cohort, with time to acknowledge beside time to close. When automation rules closed any of it, the
  // analyst-handled and automation-closed rows follow, labelled. The collector records no timing for automation
  // closures alone, so that row carries the count only.
  const r = m.response, cellOf = v => v ? esc(v.value) : 'Not available'
  const timingRows = r ? [
    ['All high severity alerts', r.n, r.acknowledge, r.median, r.p90],
    ...(r.split ? [r.split.analyst ? ['Analyst-handled', r.split.analyst.n, r.split.analyst.acknowledge, r.split.analyst.median, r.split.analyst.p90] : null, [r.split.automation.label, r.split.automation.n, null, null, null, 'Not collected']].filter(Boolean) : [])
  ] : []
  const responseDetail = r ? `<div class="timing"><h3>Response timing, high severity alerts</h3><div class="table-scroll"><table><caption>${esc(r.cohort)}</caption><thead><tr>${['Alerts', 'Closed', 'Median to acknowledge', 'Median to close', '90th percentile close'].map((h, i) => `<th scope="col"${i ? ' class="num"' : ''}>${h}</th>`).join('')}</tr></thead><tbody>${timingRows.map(([label, n, ack, median, p90, missing]) => `<tr><th scope="row">${esc(label)}</th><td class="num">${fmt(n)}</td>${[ack, median, p90].map(v => `<td class="num">${missing || cellOf(v)}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p class="small">Acknowledge is the first status change from New, by an analyst or an automation rule. Close is creation to recorded close.${r.notes.length ? ` ${esc(r.notes.join(' '))}` : ''}</p>${r.target ? `<p class="small">${esc(r.target.sentence)}</p>` : ''}${source(r.median.source)}${r.split?.analyst ? source(r.split.analyst.source) : ''}${r.target ? source(r.target.source) : ''}</div>` : ''
  const trendRows = m.trend.slice(-12)
  const SEV = SEVERITY.filter(k => k !== 'Informational' || m.trend.some(r => r.Informational > 0))
  const maxTotal = Math.max(1, ...trendRows.map(r => r.Total))
  const chart = trendRows.length ? `<div class="chart" role="img" aria-label="Alerts created each month by severity. Exact values follow in the data table.">
    ${trendRows.map(r => `<div class="chart-row"><span class="chart-month">${esc(r.label)}</span><div class="stack" style="width:${(r.Total / maxTotal * 100).toFixed(2)}%">${SEV.filter(k => r[k] > 0).map(k => `<span class="sev-${k.toLowerCase()}" style="flex:${r[k]}"></span>`).join('')}</div><strong>${fmt(r.Total)}</strong></div>`).join('')}
    <div class="legend">${SEV.map(k => `<span><i class="sev-${k.toLowerCase()}"></i>${k}</span>`).join('')}</div></div>` : '<div class="empty-state">Monthly alert figures are completed in the review.</div>'
  const trendTable = m.trend.length ? `<details class="data-details"><summary>Monthly alert data</summary><div class="table-scroll"><table><caption>Alerts created each month, ${esc(m.period.label)}</caption><thead><tr>${['Month', 'Total', ...SEV].map(v => `<th scope="col">${v}</th>`).join('')}</tr></thead><tbody>${m.trend.map(r => `<tr><th scope="row">${esc(r.label)}</th>${['Total', ...SEV].map(k => `<td>${fmt(r[k])}</td>`).join('')}</tr>`).join('')}</tbody></table></div></details>` : ''
  // The panel says closed, never resolved: a closure can carry no classification, and the unclassified count is
  // named beside the closed count. Open alerts take the model's sentence, split only by a reviewed record.
  const openPara = a => a.open > 0 ? `${fmt(a.open)} ${a.open === 1 ? 'alert was' : 'alerts were'} open at collection. ${a.openSplit ? `Of these, ${esc(a.openSplit.phrase)}.` : 'These are items referred to the client for action or confirmation under the agreed notification process, together with investigations still in progress.'}` : 'No alert created in the period was open at collection.'
  const disposition = m.alerts ? `<aside class="panel"><p class="eyebrow">Alert disposition</p>${ring(m.alerts.resolvedPct, `${fmt(m.alerts.closed)} of ${fmt(m.alerts.triaged)} alerts closed`)}<h3>${fmt(m.alerts.closed)} alerts closed</h3><p>${openPara(m.alerts)}</p>${m.alerts.unclassified > 0 ? `<p class="small">${fmt(m.alerts.unclassified)} closed ${m.alerts.unclassified === 1 ? 'alert carries' : 'alerts carry'} no recorded classification.</p>` : ''}${m.alerts.analystMode ? `<p class="small">${fmt(m.alerts.automation)} additional alerts were closed by automation rules and are shown separately from analyst activity.</p>` : m.alerts.automation ? `<p class="small">Automation rules closed ${fmt(m.alerts.automation)} of the closed alerts.</p>` : ''}${source(m.alerts.source)}${m.alerts.openSplit ? source(m.alerts.openSplit.source) : ''}</aside>` : '<aside class="panel"><p class="eyebrow">Alert disposition</p><h3>Completed in the review</h3><p>The combined alert result is reconciled before dispositions are presented.</p></aside>'
  const maxSource = m.detections ? Math.max(1, ...m.detections.bySource.map(s => s.total)) : 1
  // The period as a phrase, as the story layer words it, without the quarter label.
  const periodPhrase = m.period.valid ? `from ${esc(m.period.label)}` : 'in the period'
  const detections = m.detections ? `<div class="sources"><h3>Detections by source</h3><p class="small">${fmt(m.detections.total)} detections ${periodPhrase} were correlated into the alerts above.</p>${m.detections.bySource.slice(0, 6).map(s => `<div class="source-row"><span>${esc(s.name)}</span>${bar(s.total / maxSource * 100, `${s.name}: ${fmt(s.total)} detections`)}<strong>${fmt(s.total)}</strong></div>`).join('')}${source(m.detections.source)}</div>` : ''
  // The block prints with or without screened examples: a pack whose titles are all withheld, or whose rows carry
  // no titles or tactics, still has true positives, so the block carries the count.
  const threats = m.threats ? `<div class="threats"><h3>Confirmed threats</h3><p class="small">Alerts the SOC classified as true positives ${periodPhrase}, grouped by alert title, highest severity first.</p><div class="table-scroll"><table><caption>Confirmed threat examples</caption><thead><tr>${['Threat', 'Alerts', 'Severity', 'Attack stage', 'When'].map(h => `<th scope="col"${h === 'Alerts' ? ' class="num"' : ''}>${h}</th>`).join('')}</tr></thead><tbody>${m.threats.examples.map(t => `<tr><th scope="row">${esc(t.title)}</th><td class="num">${fmt(t.alerts)}</td><td>${esc(t.severity)}</td><td>${esc(t.stage)}</td><td>${esc(t.when).replace(/ (\d{4})/g, '&nbsp;$1')}</td></tr>`).join('')}</tbody></table></div>${m.threats.more ? `<p class="small">And ${esc(plural(m.threats.moreAlerts, 'more confirmed alert', 'more confirmed alerts'))} in ${esc(plural(m.threats.more, 'further group', 'further groups'))}.</p>` : ''}${source(m.threats.source)}</div>`
    : m.alerts && m.alerts.truePositives > 0 ? `<div class="threats"><h3>Confirmed threats</h3><p class="small">${fmt(m.alerts.truePositives)} ${m.alerts.truePositives === 1 ? 'alert' : 'alerts'} the SOC classified as ${m.alerts.truePositives === 1 ? 'a true positive' : 'true positives'} ${periodPhrase}.</p>${source(m.alerts.source)}</div>` : ''
  // The 90-day trend of the operations: alerts by week, response timing by month and the most common alert types.
  const SEV_WEEK = ['High', 'Medium', 'Low']
  const weekMax = Math.max(1, ...cs.ops.weekly.map(w => w.total))
  const weekly = cs.ops.weekly.length ? `<div class="weekly"><h3>Alerts created each week</h3><p class="small">${esc(cs.ops.weeklyNote || `Weeks run 7 days from ${cs.window.label}.`)}</p><div class="chart" role="img" aria-label="Alerts created each week by severity. Exact values follow in the data table.">${cs.ops.weekly.map(w => `<div class="chart-row"><span class="chart-month" title="${esc(w.span)}">${esc(w.label)}</span><div class="stack" style="width:${(w.total / weekMax * 100).toFixed(2)}%">${SEV_WEEK.filter(k => w[k.toLowerCase()] > 0).map(k => `<span class="sev-${k.toLowerCase()}" style="flex:${w[k.toLowerCase()]}"></span>`).join('')}</div><strong>${fmt(w.total)}</strong></div>`).join('')}<div class="legend">${SEV_WEEK.map(k => `<span><i class="sev-${k.toLowerCase()}"></i>${k}</span>`).join('')}</div></div>${source(cs.ops.weeklySource)}<details class="data-details"><summary>Weekly alert data</summary>${table(`Alerts created each week, ${cs.window.label}`, ['Week', 'Days', 'Total', ...SEV_WEEK, 'Confirmed threats'], cs.ops.weekly.map(w => [esc(w.span), fmt(w.days), fmt(w.total), fmt(w.high), fmt(w.medium), fmt(w.low), fmt(w.tp)]), [1, 2, 3, 4, 5, 6])}</details></div>` : ''
  const cellT = (t, f) => t.withheld ? 'Not reported' : t[f] === null || t[f] === undefined ? 'Not available' : esc(duration(t[f]))
  const timingNotes = cs.ops.timing.filter(t => !t.high.withheld && (t.high.belowFloor || t.high.overHour))
  const monthlyTiming = cs.ops.timing.length ? `<div class="timing"><h3>Response timing by month</h3>${table('The same cohort as above, split by the month each alert was created', ['Month', 'High: closed', 'Median to acknowledge', 'Median to close', '90th percentile', 'All: closed', 'Median to close', '90th percentile'], cs.ops.timing.map(t => [esc(t.label), fmt(t.high.n), cellT(t.high, 'ack'), cellT(t.high, 'median'), cellT(t.high, 'p90'), fmt(t.all.n), cellT(t.all, 'median'), cellT(t.all, 'p90')]), [1, 2, 3, 4, 5, 6, 7])}<p class="small">A month with fewer than 5 closed alerts in a column reports no timing for it.${timingNotes.length ? ` ${esc(list(timingNotes.map(t => t.label)))} ${timingNotes.length === 1 ? 'carries' : 'carry'} a median under 20 minutes or a 90th percentile over one hour, covered in the review.` : ''}</p>${source(cs.ops.timingSource)}</div>` : ''
  const alertTypes = cs.ops.types.length ? `<div class="threats"><h3>Most common alert types</h3>${table(`Alert types over ${periodWord}, most frequent first`, ['Alert type', 'Over the period', `In ${cs.month.short}`, 'High severity', 'Confirmed threats'], cs.ops.types.map(t => [esc(t.title), fmt(t.total), fmt(t.month), fmt(t.high), fmt(t.tp)]), [1, 2, 3, 4])}${cs.ops.typesWithheld ? `<p class="small">${esc(plural(cs.ops.typesWithheld, 'alert whose title names an account, address, host or ticket is', 'alerts whose titles name an account, address, host or ticket are'))} counted without the title.</p>` : ''}${source(cs.ops.typesSource)}</div>` : ''
  const outcomes = `<section class="page balanced-only" id="outcomes">${heading('02', 'Security operations', 'What the managed security service handled, and how quickly')}
    <div class="page-body"><p class="section-scope">${scopeLine}</p>${responseStrip}${responseDetail}
    <div class="two-col"><div><h3>Alerts ${m.ticketed ? 'worked' : 'created'} each month</h3><p class="small">${m.ticketed ? 'Each alert opened a ticket and was worked inside the managed service. Volume reflects detection coverage and activity across the environment.' : 'Volume reflects detection coverage and activity across the environment. Each alert is triaged inside the managed service.'}</p>${chart}${trendRows.length < m.trend.length ? '<p class="small">Chart shows the most recent 12 months. The table contains the full period.</p>' : ''}${source(m.trendSource)}${m.trendCoverage ? `<p class="small">${esc(m.trendCoverage.sentence)} ${esc(m.trendCoverage.caption)}</p>${source(m.trendCoverage.source)}` : ''}${trendTable}${detections}</div>${disposition}</div>${weekly}${monthlyTiming}${alertTypes}${threats}
    <div class="decision-note"><h3>How to read this page</h3><p>${m.ticketed ? 'An alert is a Sentinel record that opened a ticket with the managed security service. Informational severity is excluded, and detections are the alerts correlated into those tickets.' : m.detections && m.detections.allSources ? `Detections from ${esc(m.detections.allSources)} are correlated into alerts.` : 'Detections are correlated into alerts.'}${m.xdrScope.sentence ? ' ' + esc(m.xdrScope.sentence) : ''} The SOC triages each alert, and a closure records its classification when the SOC sets one${m.response ? `. Response times are measured from alert creation to recorded close for ${esc(m.response.cohort.charAt(0).toLowerCase() + m.response.cohort.slice(1))}` : ''}.</p></div>
    </div>${footer('02', 'Security operations')}</section>`

  // 03 Threat intelligence: what the threat intelligence and the detections show about this environment.
  const ti = cs.threat
  const notGathered = items => items.length ? `<p class="small not-gathered">Completed in the review: ${esc(list(items.map(u => u.label.toLowerCase())))}.</p>` : ''
  const tiTiles = ti.tiles
  const stageMax = ti.stages ? Math.max(1, ...ti.stages.rows.map(t => t.alerts)) : 1
  const stages = ti.stages ? `<div class="stages-observed"><h3>Attack stages on the alerts</h3><p class="small">The MITRE ATT&CK tactics Sentinel recorded on the detections in the alerts over ${periodWord}, in attack chain order. One alert can carry several tactics. A tactic is a label recorded at detection, not an investigation finding.</p>${ti.stages.rows.length ? ti.stages.rows.map(t => `<div class="stage-row"><span>${esc(t.label)}</span>${bar(t.alerts / stageMax * 100, `${t.label}: ${fmt(t.alerts)} alerts`)}<strong>${fmt(t.alerts)}</strong><span class="small">${fmt(t.month)} in ${esc(cs.month.short)}${t.tp ? `, ${fmt(t.tp)} confirmed` : ''}</span></div>`).join('') : '<p class="small">No tactic was recorded on the alerts in the period.</p>'}${source(ti.stages.source)}</div>` : ''
  const techniques = ti.techniques && ti.techniques.rows.length ? `<div><h3>Attack techniques observed</h3>${table('MITRE ATT&CK techniques on the same detections', ['Technique', 'Alerts', 'Confirmed threats'], ti.techniques.rows.map(t => [esc(t.label), fmt(t.alerts), fmt(t.tp)]), [1, 2])}${source(ti.techniques.source)}</div>` : ''
  const matches = ti.matches ? `<div><h3>Threat intelligence matches</h3><p class="small">Detections from the threat intelligence analytics rules: a known malicious indicator observed in your telemetry. A match is an observation, not an investigation finding.</p>${table('', ['Month', 'Matches', 'In ticketed alerts'], ti.matches.byMonth.map(x => [esc(x.label), fmt(x.total), fmt(x.ticketed)]), [1, 2])}${ti.matches.byType.length ? `<p class="small">By indicator type over ${periodWord}: ${esc(list(ti.matches.byType.map(t => `${t.type} ${fmt(t.total)}`)))}.</p>` : ''}${source(ti.matches.source)}</div>` : ''
  const indicators = ti.indicators ? `<aside class="panel"><p class="eyebrow">Threat intelligence coverage</p><h3>${fmt(ti.indicators.active)} active indicators</h3><p>Of ${fmt(ti.indicators.total)} indicators on record at the end of the period, from ${esc(list(ti.indicators.feeds.map(f => f.name)))}${ti.indicators.feedCount > ti.indicators.feeds.length ? ' and other feeds' : ''}.</p>${table('', ['Type', 'Indicators', 'Active'], ti.indicators.byKind.map(k => [esc(k.kind), fmt(k.total), fmt(k.active)]), [1, 2])}${source(ti.indicators.source)}</aside>` : ''
  const id = ti.identity
  const idRows = id ? [['Failed password sign-ins', 'failedPassword'], ['Accounts with a failed password', 'targeted'], ['Password spraying sources', 'sprayIps'], ['Smart lockouts and blocked addresses', 'lockouts'], ['Sign-ins blocked by Conditional Access', 'blocked'], ...(id.riskVisible ? [['Medium and high risk sign-ins', 'risky'], ['Risky sign-ins that succeeded', 'riskySuccess']] : [])] : []
  const identity = id ? `<div class="threats"><h3>Identity threat activity</h3><p class="small">Interactive sign-ins by month. A password spraying source is an address that failed a password against ${fmt(EbrCyberSoc.SPRAY_TARGETS)} or more accounts in one day, a signal rather than a confirmed attack.${id.riskVisible ? '' : ' Sign-in risk levels are not visible to this collection, so risky sign-ins are not shown.'}</p>${table('', ['Measure', ...id.byMonth.map(x => x.label)], idRows.map(([label, f]) => [esc(label), ...id.byMonth.map(x => fmt(x[f]))]), range(id.byMonth.length))}${source(id.source)}</div>` : ''
  const risk = ti.risk && ti.risk.rows.length ? `<div><h3>Identity risk detections</h3>${table('Microsoft Entra ID Protection risk detections', ['Detection', 'Over the period', `In ${cs.month.short}`, 'High risk'], ti.risk.rows.map(r => [esc(r.label), fmt(r.total), fmt(r.month), fmt(r.high)]), [1, 2, 3])}${source(ti.risk.source)}</div>` : ''
  const email = ti.email ? `<div class="threats"><h3>Email threats</h3>${table('Inbound mail by month', ['Month', 'Messages', 'Phishing', 'Malware', 'Spam', 'Threats kept from the inbox', 'Threats delivered'], ti.email.byMonth.map(x => [esc(x.label), fmt(x.messages), fmt(x.phish), fmt(x.malware), fmt(x.spam), fmt(x.blocked), fmt(x.delivered)]), [1, 2, 3, 4, 5, 6])}<p class="small">Threats delivered counts the first delivery only. Zero-hour auto purge can remove a message after delivery.</p>${source(ti.email.source)}</div>` : ''
  const malware = ti.malware ? `<div class="threats"><h3>Malware detected on Azure virtual machines</h3>${ti.malware.rows.length ? table('Microsoft Defender Antivirus detections, last 30 days', ['Threat', 'Detections', 'Machines', 'Reported remediated'], ti.malware.rows.map(r => [esc(r.threat), fmt(r.detections), fmt(r.devices), fmt(r.remediated)]), [1, 2, 3]) : '<p class="small">Microsoft Defender Antivirus recorded no detection on the Azure virtual machines in the last 30 days.</p>'}${source(ti.malware.source)}</div>` : ''
  const vk = cs.vuln
  const kev = vk.mode === 'runs' && vk.kevKnown ? `<div class="threats"><h3>Known exploited vulnerabilities in your environment</h3><p class="small">Open findings in the assessment of ${esc(vk.latest ? vk.latest.label : 'the latest run')} whose CVEs are in the CISA Known Exploited Vulnerabilities catalog. A listing means CISA has reported exploitation in the wild, not that the vulnerability was exploited here.</p>${vk.kev.length ? table('', ['Product', 'Severity', 'Virtual machines', 'Added to the CISA catalog'], vk.kev.map(k => [esc(k.product), esc(k.severity), fmt(k.vms), `${esc(k.added)}${k.thisMonth ? ` (in ${esc(cs.month.label)})` : ''}`]), [2]) : '<p class="small">No open finding carries a CVE CISA lists as known exploited.</p>'}${source(vk.kevSource)}</div>` : ''
  const threatPage = `<section class="page" id="threat">${heading('03', 'Threat intelligence', 'The threats observed in your environment, and the intelligence they were matched against')}
    <div class="page-body"><p class="section-scope">${scopeLine}</p>${tileStrip(`Threat intelligence · ${cs.month.label} and ${periodWord}`, tiTiles)}
    ${stages}<div class="two-col even">${techniques}${risk}</div><div class="two-col">${matches}${indicators}</div>${identity}${email}${malware}${kev}${notGathered(ti.unmeasured)}
    <div class="decision-note"><h3>How to read this page</h3><p>Threat intelligence matches and attack stages describe what the detections recorded, not investigation findings. A threat intelligence match confirms an indicator was observed in your telemetry. Confirmed threats are alerts the SOC classified as true positives. A CISA KEV listing means CISA has reported exploitation of the vulnerability in the wild, not exploitation in your environment.</p></div>
    </div>${footer('03', 'Threat intelligence')}</section>`

  // 04 Vulnerability management: the monthly assessment runs, or the current Defender reading without them.
  const ownerText = v => v.owners.map(o => `${o.owner} ${fmt(o.n)}`)
  const exploitText = t => t.kev ? 'CISA KEV listed' : t.exploit ? 'Public exploit code' : 'None reported'
  let vulnBody = ''
  const vulnTiles = vk.tiles
  if (vk.mode === 'runs' && vk.latest) {
    const L = vk.latest, c = vk.change
    const runsTable = table('Open findings at each assessment in the window', ['Assessment', 'Critical', 'High', 'Medium', 'Low', 'Open', 'CISA KEV', 'Public exploit', 'Virtual machines'], vk.runs.map(r => [`${esc(r.label)}${r.complete ? '' : ' (partial)'}`, fmt(r.critical), fmt(r.high), fmt(r.medium), fmt(r.low), fmt(r.open), r.kev === null ? 'Not checked' : fmt(r.kev), r.exploit === null ? 'Not checked' : fmt(r.exploit), fmt(r.vms)]), [1, 2, 3, 4, 5, 6, 7, 8])
    const changeRows = vk.changes.filter(x => x.compared)
    const changes = vk.changes.length ? `<div><h3>Change between assessments</h3>${changeRows.length ? table('Open findings, a finding being one virtual machine and one vulnerable software', ['Between', 'New', 'No longer open', 'Open after'], changeRows.map(x => [esc(x.label), fmt(x.openNew), fmt(x.openGone), fmt(x.openNow)]), [1, 2, 3]) : ''}<p class="small">A finding no longer open is pending validation, never counted as remediated. Assessments are compared only when both covered every subscription with complete data and the same severity filter${vk.changes.length > changeRows.length ? `, so ${plural(vk.changes.length - changeRows.length, 'pair is', 'pairs are')} not compared` : ''}.</p>${source(vk.changeSource)}</div>` : ''
    const statusMax = Math.max(1, ...vk.statuses.map(x => x.n))
    const statuses = vk.statuses.length ? `<aside class="panel"><p class="eyebrow">Remediation status</p><h3>Where the findings stand</h3>${vk.statuses.map(x => `<div class="source-row"><span>${esc(x.label)}</span>${bar(x.n / statusMax * 100, `${x.label}: ${fmt(x.n)}`)}<strong>${fmt(x.n)}</strong></div>`).join('')}${vk.owners.length ? `<p class="small">Open findings by owner: ${esc(list(ownerText(vk)))}.</p>` : ''}${L.eos ? `<p class="small">${esc(plural(L.eos, 'virtual machine runs', 'virtual machines run'))} an end-of-support operating system, which needs a migration plan as well as patching.</p>` : ''}${L.noFix ? `<p class="small">${esc(plural(L.noFix, 'open finding has', 'open findings have'))} no vendor fix yet and ${L.noFix === 1 ? 'is' : 'are'} monitored.</p>` : ''}${source(vk.source)}</aside>` : ''
    const top = vk.top.length ? `<div class="threats"><h3>Top products to patch</h3>${table('Open findings by product, ranked by CISA KEV listing, public exploit code, CVSS and reach', ['Product', 'Severity', 'Virtual machines', 'CVEs', 'Exploit intelligence', 'Max CVSS', 'Vendor fix', 'Owner'], vk.top.map(t => [esc(t.product), esc(t.severity), fmt(t.vms), fmt(t.cves), esc(exploitText(t)), t.cvss === null ? 'Not scored' : fmt(t.cvss), esc(t.fix), esc(t.owner)]), [2, 3, 5])}${source(vk.topSource)}</div>` : ''
    const cross = vk.defender ? `<p class="small">Defender vulnerability management reads ${esc(plural(vk.defender.cves, 'CVE', 'CVEs'))} open on Azure virtual machines at collection, ${fmt(vk.defender.exploitable)} with public exploit code.</p>${source(vk.defender.source)}` : ''
    vulnBody = `<h3>Open findings over the window</h3>${runsTable}${source(vk.source)}<div class="two-col">${changes}${statuses}</div>${top}${cross}`
  } else if (vk.mode === 'defender') {
    const D = vk.defender
    vulnBody = `${table('Open CVEs on Azure virtual machines by severity, current state', ['Severity', 'CVEs', 'Machines', 'Exposures', 'With public exploit'], D.bySeverity.map(x => [esc(x.level), fmt(x.cves), fmt(x.devices), fmt(x.exposures), fmt(x.exploitable)]), [1, 2, 3, 4])}${source(D.source)}${D.software.length ? `<h3>Most exposed software</h3>${table('', ['Software', 'Machines', 'CVEs', 'Critical', 'High', 'With public exploit'], D.software.map(x => [esc(x.name), fmt(x.devices), fmt(x.cves), fmt(x.critical), fmt(x.high), fmt(x.exploitable)]), [1, 2, 3, 4, 5])}${source(D.softwareSource)}` : ''}${D.publishedKnown ? `<h3>New exposure each month</h3>${table('CVEs published in each month of the window that are open at collection', ['Month', 'CVEs', 'Critical', 'High', 'With public exploit'], D.published.map(x => [esc(x.label), fmt(x.cves), fmt(x.critical), fmt(x.high), fmt(x.exploitable)]), [1, 2, 3, 4])}${source(D.publishedSource)}` : ''}<p class="small">The monthly vulnerability assessment adds the CISA KEV listing, the remediation status and owner of each finding, and the change between months.</p>`
  } else vulnBody = '<div class="empty-state">The vulnerability position is completed in the review.</div>'
  const vulnPage = `<section class="page" id="vulnerability">${heading('04', 'Vulnerability management', 'The vulnerabilities open on your Azure virtual machines, what changed, and who remediates them')}
    <div class="page-body"><p class="section-scope">${vk.mode === 'runs' ? `Atmosera vulnerability assessment, ${esc(plural(vk.runs.length, 'run', 'runs'))} in the window, latest ${esc(vk.latest ? vk.latest.label : 'not recorded')}.` : vk.mode === 'defender' ? `Defender vulnerability management, Azure virtual machines, read ${esc(m.readDate)}.` : esc(scopeLine)}</p>${tileStrip(`Vulnerability management · ${cs.month.label}`, vulnTiles)}${vulnBody}
    <div class="decision-note"><h3>How to read this page</h3><p>A finding is one vulnerable software package on one virtual machine and usually covers several CVEs. Public exploit code means exploit code is published, and a CISA KEV listing means CISA has reported exploitation in the wild. Neither means the vulnerability was exploited in your environment. A finding no longer reported is pending validation until the next assessment confirms it.</p></div>
    </div>${footer('04', 'Vulnerability management')}</section>`

  // 05 Measured outcomes across every pillar
  const pillarRows = m.pillars.map((p, i) => `<article class="pillar-row"><div class="pillar-name"><span>0${i + 1}</span><h3>${esc(p.name)}</h3></div><div class="pillar-story"><h4>${esc(p.headline)}</h4><p>${esc(p.narrative)}</p>${source(p.source)}</div><div class="pillar-measure">${p.measure ? `<p class="measure-label">${esc(p.measure.label)}</p>${bar(p.measure.pct, `${p.measure.label}: ${fmt(p.measure.good)} of ${fmt(p.measure.total)}`, p.measure.pct >= 95 ? 'green' : '')}<strong>${fmt(p.measure.good)} of ${fmt(p.measure.total)}</strong>` : ''}</div><div class="pillar-callout">${p.callout ? `<strong>${esc(p.callout.value)}</strong><span>${esc(p.callout.label)}</span>` : ''}</div></article>`).join('')
  const measured = `<section class="page balanced-only" id="measured">${heading('05', 'Measured outcomes across every pillar', 'Each pillar and the outcome it produced')}
    <div class="page-body"><p class="section-scope">${scopeLine}</p><div class="pillars">${pillarRows}</div>
    <div class="decision-note"><h3>Why this matters</h3><p>Detection and response is the pillar Atmosera operates directly. The pillars that read lower are the ones that need change inside the client infrastructure, and each of those items is on the proposed roadmap. A vendor hands you a percentage. This is a program somebody runs.</p></div>
    </div>${footer('05', 'Measured outcomes')}</section>`

  // 06 The controls that matter
  const groups = ['Identity and access', 'Endpoint and workload', 'Network and boundary', 'Data protection', 'Detection and response']
  const nullRow = c => `<div class="control-row unmeasured"><span class="mark mark-null" title="Not gathered" aria-hidden="true"></span><div class="control-text"><h4>${esc(c.label)}</h4><p>${esc(c.note)}</p>${source(c.source)}</div><div class="control-measure"><strong>${esc(c.value)}</strong><span>Not gathered</span></div></div>`
  const naRow = c => `<div class="control-row unmeasured not-applicable"><span class="mark mark-null" title="No evidence either way" aria-hidden="true"></span><div class="control-text"><h4>${esc(c.label)}</h4><p>${esc(c.note)}</p>${source(c.source)}</div><div class="control-measure"><strong>${esc(c.value)}</strong><span>No evidence either way</span></div></div>`
  // The measure column: the figure, a bar for every measured ratio (a Mostly enforced policy carries the sign-in
  // ratio behind it), then the share and what the control is missing, such as the resource types outside coverage.
  // A share counted against part of a population names it, such as the members evaluated for MFA at sign-in, and a
  // figure too large for the bar names that population in place of sign-ins.
  const per = c => c.per ? ` ${esc(c.per)}` : ''
  const measureText = c => c.boolean ? (c.ratioText ? `${esc(c.ratioText)} · ${pctText(c.pct)}${per(c)}` : '') : c.total > 9999 ? `${esc(c.value)} ${c.per ? esc(c.per.replace(/^of /, '')) : 'sign-ins'}` : `${pctText(c.pct)}${c.estimate ? ' estimated' : ''}${per(c)}`
  const gapText = c => c.gap ? `<span class="gap">${esc(c.gap)}</span>` : ''
  const exceptionsLine = c => exceptionText(c) ? `<span class="exceptions">${esc(exceptionText(c))}</span>` : ''
  const sampleLine = c => sampleText(c) ? `<span class="small-sample">${esc(c.mark)}, ${esc(sampleText(c))}</span>` : ''
  const populationsLine = c => c.populations ? `<span class="populations">${esc(c.populations)}</span>` : ''
  const controlRow = c => c.na ? naRow(c) : c.measured === false ? nullRow(c) : `<div class="control-row">${markChip(c.mark, exceptionText(c), sampleText(c))}<div class="control-text"><h4>${esc(c.label)}</h4><p>${esc(c.note)}</p>${source(c.source)}</div><div class="control-measure"><strong>${esc(c.boolean ? c.value : c.total > 9999 ? pctText(c.pct) : c.value)}</strong>${c.boolean && !c.ratioText ? '' : bar(c.pct, `${c.label}: ${c.ratioText || c.value}`, c.mark === 'E' ? 'green' : c.mark === 'N' ? 'amber' : '')}<span>${measureText(c)}</span>${populationsLine(c)}${exceptionsLine(c)}${sampleLine(c)}${gapText(c)}</div></div>`
  // Each pillar shows its foundational controls on the left and its defense in depth controls on the right.
  const tierCols = [['foundational', 'Foundational'], ['defense', 'Defense in depth']]
  const tierCol = (items, tier, label) => {
    const rows = items.filter(c => c.tier === tier)
    const measured = rows.filter(c => c.measured !== false && c.pct !== null)
    const count = measured.length ? `${measured.filter(c => c.mark === 'E').length} of ${measured.length} enforced${smallNote(measured.filter(c => c.smallSample).length)}` : rows.length && rows.every(c => c.na) ? 'Not applicable' : rows.length ? 'Not gathered' : ''
    return `<div class="control-col ${tier}"><p class="tier-label"><span class="tier-name">${esc(label)}</span><span class="tier-count">${esc(count)}</span></p>${rows.map(controlRow).join('') || '<p class="tier-empty">Nothing to show for this pillar in this collection.</p>'}</div>`
  }
  const matrix = groups.map((group, i) => {
    const items = m.controls.filter(c => c.group === group)
    const counts = { E: items.filter(c => c.mark === 'E').length, P: items.filter(c => c.mark === 'P').length, N: items.filter(c => c.mark === 'N').length, U: items.filter(c => c.measured === false && !c.na).length, A: items.filter(c => c.na).length }
    return `<section class="pillar"><div class="pillar-head"><span>0${i + 1}</span><h3>${group}</h3><p class="small">${items.length ? `${counts.E} enforced · ${counts.P} partial · ${counts.N} not yet enforced${counts.U ? ` · ${counts.U} not gathered` : ''}${counts.A ? ` · ${counts.A} not applicable` : ''}` : 'Readings completed in the review'}</p></div><div class="control-list">${items.length ? tierCols.map(([tier, label]) => tierCol(items, tier, label)).join('') : '<p class="small">Evidence for this pillar is confirmed from the portal during the review.</p>'}</div></section>`
  }).join('')
  const controls = `<section class="page balanced-only" id="controls">${heading('06', 'The controls that matter', 'The standards we hold this environment to, and the status of each')}
    <div class="page-body"><p class="section-scope">Posture read ${esc(m.readDate)}. Activity lookbacks are stated with each measure.</p>
    <div class="legend-box"><h3>Two tiers of controls</h3><p><strong>Foundational</strong> controls are the baseline the managed security service holds every environment to, and each is expected to read enforced at every review. One that reads below E is a gap against that baseline and carries a fix date. <strong>Defense in depth</strong> controls are the additional safeguards layered on top. Each waits on something your team approves, schedules or licenses, and they are sequenced on the roadmap.</p>
    <h3>What the status marks mean</h3><p><span class="mark mark-e">E</span> Enforced on 90 percent or more of in-scope resources. <span class="mark mark-p">P</span> Partial, enforced on 50 to 89 percent. <span class="mark mark-n">N</span> Not yet enforced, under 50 percent. A ratio control at E that still leaves resources out shows how many as exceptions beside its figure, so meeting the threshold reads differently from complete coverage. A ratio control measured on fewer than ${fmt(MIN_SAMPLE)} resources, or with more machines left out by tag than assessed, is marked small sample. It keeps its mark and its place in the counts, and each count that holds one says so. A policy control reads In force when the policy covers every user on every application in every condition, Mostly enforced when an enabled policy stops short of that, by selecting its users or applications or by a platform, risk level, device filter or location condition, and at least half of the measured sign-ins still satisfied it, and Not in force otherwise. A policy in force whose exclusions let sign-ins through shows how many accounts made them beside the reading, for example 2 accounts with excluded sign-ins. The percentage bands apply to ratio controls. A policy that stops short of every user on every application in every condition reads P however high the sign-in ratio behind it, because the policy itself is not in force everywhere. A control reading (null) could not be gathered in this collection and is confirmed from the portal during the review. A control reading N/A had no activity or configuration in this collection to judge it by, so it carries no status. Every reading describes the state at collection, not a change since the last review.</p></div>
    <div class="control-matrix">${matrix}</div></div>${footer('06', 'The controls that matter')}</section>`

  // 07 Delivered and sequenced
  const priorityRow = (p, i) => `<article class="priority"><div class="priority-index">${String(i + 1).padStart(2, '0')}</div><div><p class="eyebrow dark">${i === 0 ? 'First workstream' : 'Sequenced'}</p><h3>${esc(p.title)}</h3><p class="priority-evidence">${esc(p.evidence)}</p><p>${esc(p.action)}</p><p class="success"><strong>Outcome</strong> ${esc(p.success)}</p>${source(p.source)}</div></article>`
  const delivered = m.delivered.length ? `<div class="delivered"><p class="eyebrow dark">Delivered through the managed security service</p><div class="delivered-grid">${m.delivered.map(d => `<article><h3>${esc(d.title)}</h3><p>${esc(d.outcome)}</p>${source(`${d.reference}. Completed ${d.date}.${d.pillar ? ' ' + d.pillar + '.' : ''}`)}</article>`).join('')}</div></div>` : ''
  // The MFA method update: users still on text message or voice move to a stronger method before Microsoft
  // retires those methods. Never framed as a passwordless programme (Oct 14, 2026).
  const mfaMethods = m.mfaMethods && m.mfaMethods.retiring > 0 ? `<div class="mfa-methods"><div><p class="eyebrow">Identity · MFA method update</p><h3>${fmt(m.mfaMethods.retiring)} of your users signed in with text message or voice over the last 30 days. Atmosera recommends moving each one to a passkey well ahead of ${esc(m.mfaMethods.deadline)}.</h3><p>${esc(m.mfaMethods.timeline)} ${esc(m.mfaMethods.reliance)}${m.mfaMethods.authenticator > 0 ? ` ${fmt(m.mfaMethods.authenticator)} ${m.mfaMethods.authenticator === 1 ? 'user' : 'users'} signed in with the Microsoft Authenticator app or an OTP token.` : ''}${m.mfaMethods.resistant > 0 ? ` ${fmt(m.mfaMethods.resistant)} ${m.mfaMethods.resistant === 1 ? 'user already signs' : 'users already sign'} in with a phishing-resistant method.` : ''}</p>${source(m.mfaMethods.source)}</div><ol class="steps">${m.mfaMethods.steps.map(([head, body], i) => `<li><span>${i + 1}</span><div><strong>${esc(head)}</strong>${esc(body)}</div></li>`).join('')}</ol><p class="success"><strong>Outcome</strong> ${esc(m.mfaMethods.outcome)}</p></div>` : ''
  const roadmap = `<section class="page" id="roadmap">${heading('07', m.delivered.length ? 'Delivered and sequenced' : 'What comes next', 'The hardening sequence that follows, grouped by the outcome each item moves')}
    <div class="page-body"><p class="section-scope">Priorities reflect the evidence collected ${esc(m.readDate)}. Atmosera recommends staging each enforcement in an audit or report-only mode where the control supports one, reviewing it with your team, then turning it on.</p>${delivered}
    <div class="priorities">${m.priorities.slice(0, 3).map(priorityRow).join('')}</div>
    ${m.priorities.length > 3 ? `<details class="additional"><summary>Also sequenced (${m.priorities.length - 3})</summary>${m.priorities.slice(3).map((p, i) => priorityRow(p, i + 3)).join('')}</details>` : ''}
    <div class="stages"><div><span>01</span><h3>Confirm</h3><p>Validate affected workloads, business impact and the intended control scope.</p></div><div><span>02</span><h3>Pilot</h3><p>Stage approved changes in report-only mode with the client team and document exceptions.</p></div><div><span>03</span><h3>Verify</h3><p>Recollect the evidence and confirm the outcome at the next review.</p></div></div>
    ${mfaMethods}
    <div class="decision-note"><h3>How this order is proposed</h3><p>Every item on this board comes from a reading in the collected evidence. The order is a recommendation for agreement at this review: the highest-priority items go first through your change control process, with the remainder behind them in deliberate order.</p></div>
    </div>${footer('07', 'Roadmap')}</section>`

  // 08 Posture in context, with the scores over the window
  const pc = cs.posture
  const scoreTrend = pc.cloud.some(x => x.pct !== null) || pc.tenant.some(x => x.pct !== null) ? `<div class="score-trend"><h3>Scores over ${esc(periodWord)}</h3>${table('Each score is a percentage of the maximum it was read against. A month whose maximum changed is not compared with the one before it.', ['Score', ...cs.months.map(x => x.label)], [pc.cloud.some(x => x.pct !== null) ? ['Defender for Cloud score', ...pc.cloud.map(x => x.pct === null ? 'Not available' : esc(pctText(x.pct)))] : null, pc.tenant.some(x => x.pct !== null) ? ['Microsoft Secure Score', ...pc.tenant.map(x => x.pct === null ? 'Not available' : esc(pctText(x.pct)))] : null].filter(Boolean), range(cs.months.length))}${pc.cloud.some(x => x.pct !== null) ? source(pc.cloudSource) : ''}${pc.tenant.some(x => x.pct !== null) ? source(pc.tenantSource) : ''}${pc.health.length > 1 ? `<h4>Recommendations healthy, by week</h4>${sparkline(pc.health, 'Share of Defender for Cloud recommendations healthy, by week')}${source(pc.healthSource)}` : ''}</div>` : ''
  // Each score reads as a percentage with its movement in percentage points from the starting reading, never as
  // points available (Oct 14, 2026).
  const cloudCard = m.cloudScore ? `<article class="score-card"><p class="eyebrow">Defender for Cloud · Your Azure resource estate</p><div class="score-main">${ring(m.cloudScore.value, `Defender for Cloud score ${pctText(m.cloudScore.value)}`)}<div><h3>${esc(pctText(m.cloudScore.value))}</h3><p>${esc(m.cloudScore.note)}${m.posture.assessed !== null ? ` Measured across ${fmt(m.posture.assessed)} assessed resources.` : ''}</p>${m.cloudScore.delta && m.cloudScore.delta.points > 0 ? `<p class="up">Up ${fmt(m.cloudScore.delta.points)} points since ${esc(m.cloudScore.delta.since)}, from ${esc(pctText(m.cloudScore.delta.from))}</p>` : '<p class="small">Reported as current state.</p>'}</div></div>${sparkline(m.cloudScore.trend, 'Defender for Cloud score by month')}${source(m.cloudScore.source)}</article>` : '<article class="score-card"><p class="eyebrow">Defender for Cloud</p><h3>Reading completed in the review</h3></article>'
  const tenantCard = m.tenantScore ? `<article class="score-card"><p class="eyebrow">Microsoft Secure Score · Your Microsoft 365 tenant</p><div class="score-main">${ring(m.tenantScore.value, `Tenant Secure Score ${pctText(m.tenantScore.value)}`)}<div><h3>${esc(pctText(m.tenantScore.value))}</h3><p>${esc(m.tenantScore.note)}</p>${m.tenantScore.delta ? `<p class="up">Up ${fmt(m.tenantScore.delta.points)} points since ${esc(m.tenantScore.delta.since)}, from ${esc(pctText(m.tenantScore.delta.from))}</p>` : ''}</div></div>${m.tenantScore.categories.length ? `<div class="categories">${m.tenantScore.categories.map(c => `<div><span>${esc(c.label)}</span>${bar(c.pct, `${c.label} ${pctText(c.pct)}`)}<strong>${esc(pctText(c.pct))}</strong></div>`).join('')}</div>` : ''}${source(m.tenantScore.source)}</article>` : '<article class="score-card muted"><p class="eyebrow">Microsoft Secure Score · Your Microsoft 365 tenant</p><h3>Added from the portal reading</h3><p class="small">The tenant score is read in the Defender portal and added through the review context so both estates are presented together.</p></article>'
  const meters = [m.posture.highHealthy ? { label: 'High severity assessments healthy', value: `${fmt(m.posture.highHealthy.good)} of ${fmt(m.posture.highHealthy.total)}`, pct: m.posture.highHealthy.pct, source: m.posture.highHealthy.source } : null, m.posture.benchmark ? { label: 'Microsoft cloud security benchmark controls passed', value: `${fmt(m.posture.benchmark.passed)} of ${fmt(m.posture.benchmark.total)}`, pct: m.posture.benchmark.pct, source: m.posture.benchmark.source } : null].filter(Boolean)
  const scoreControls = m.posture.scoreControls.length ? `<h3>Where the next points are</h3><p class="small">Microsoft score controls ranked by the points still available. ${esc(m.posture.scoreControlBasis)}</p><div class="score-controls">${m.posture.scoreControls.slice(0, 10).map(c => `<div><div><h4>${esc(c.label)}</h4>${c.resources ? `<p class="small">${fmt(c.healthy)} of ${fmt(c.resources)} ${c.resources === 1 ? 'resource' : 'resources'} healthy</p>` : ''}</div>${bar(c.pct, `${c.label}: ${pctText(c.pct)}`)}<strong>${esc(pctText(c.pct))}</strong><span>${fmt(c.remaining)} ${c.remaining === 1 ? 'point' : 'points'} available</span></div>`).join('')}</div>${source(m.posture.scoreControlSource)}` : ''
  const posture = `<section class="page balanced-only" id="posture">${heading('08', 'Tenant and cloud security posture', 'Microsoft calculates both of these scores. We report them as benchmark and context, and we do not manage the environment to them.')}
    <div class="page-body"><div class="two-col even">${cloudCard}${tenantCard}</div>${scoreTrend}
    ${meters.length ? `<div class="meters">${meters.map(x => `<div class="meter"><div class="meter-head"><h4>${esc(x.label)}</h4><strong>${esc(x.value)}</strong></div>${bar(x.pct, `${x.label}: ${x.value}`)}<span class="small">${esc(pctText(x.pct))}</span>${source(x.source)}</div>`).join('')}</div>` : ''}
    ${scoreControls}
    <div class="explainer"><p class="eyebrow dark">Microsoft changed how Secure Score is calculated</p><p>A score movement can reflect a change in the measurement model, the scope or the weighting rather than a change in your controls. Through 2026 Microsoft widened what counts as an assessed resource, restated history when Defender for Cloud moved into the Defender portal, and began counting nested findings individually. The denominator, the weighting and the evaluated scope can all move the percentage while the underlying configuration has not changed. We track the controls behind the score, not the percentage alone.</p></div>
    <div class="inventory"><div><span class="big-number">${fmt(m.posture.estate)}</span><h3>Azure resources in the estate</h3><p class="small">${m.excluded ? `Managed resource groups matching ${esc(m.excluded)} are excluded.` : 'No managed resource group exclusion was configured.'}</p></div><div><span class="big-number">${fmt(m.posture.assessed)}</span><h3>Resources assessed by Defender for Cloud</h3><p class="small">Distinct resources in assessment records at collection.</p></div><div><span class="big-number">${m.posture.rules ? fmt(m.posture.rules.enabled) : fmt(m.posture.telemetryTables)}</span><h3>${m.posture.rules ? 'Analytics rules active in Sentinel' : 'Telemetry tables collected'}</h3><p class="small">${m.posture.rules ? `Of ${fmt(m.posture.rules.total)} rules across ${m.workspaces.length} ${m.workspaces.length === 1 ? 'workspace' : 'workspaces'}.` : 'Distinct data types reaching the workspaces.'}</p></div></div>
    <h3>Sentinel collection scope</h3><div class="table-scroll"><table><thead><tr><th scope="col">Workspace</th><th scope="col">Retention</th></tr></thead><tbody>${m.workspaces.map(w => `<tr><td>${esc(w.Name)}</td><td>${fmt(w.RetentionDays)} days</td></tr>`).join('')}</tbody></table></div><p class="small">Tenant-wide sign-in readings use ${esc(m.tenantWorkspace)}. Alert metrics come from one combined query across the workspaces. Workspace medians and distinct counts are never added together.</p>
    </div>${footer('08', 'Posture in context')}</section>`

  report.innerHTML = summary + outcomes + threatPage + vulnPage + measured + controls + roadmap + posture
  document.title = `${m.client} | CyberSOC monthly security report, ${cs.month.label}`

  // The depth selector and the print button are wired by report-controls.js, which both editions carry.
  document.getElementById('depth').value = m.depth
})()
